/**
 * O sistema solar — uma cena, três modos.
 *
 * Os três puzzles do arquétipo `solar` ("As Leis do Movimento", "O Escudo da
 * Terra" e "Variáveis da Criação") nunca declararam viz nenhuma: a tela mostrava
 * sliders e leitura, e canvas nenhum. A fiação para isto já existia inteira —
 * `montarViz` repassa `puzzle.solar.modo` em `opcoes.modo`, `lancar` só existe
 * para o lançamento e `aoMudarEstado` é por onde o desfecho volta —, e é por isso
 * que os três cabem num arquivo só, escolhendo o desenho pelo modo.
 *
 * **A trajetória é integrada de verdade**, e não roteirizada: a esfera recebe a
 * velocidade do slider e é puxada pelo Sol quadro a quadro. Cair, escapar ou
 * ficar em órbita é o que acontece, não o que foi decidido de antemão — e é a
 * única forma de o "devagar demais cai, rápido demais escapa" ser uma
 * descoberta em vez de um aviso.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  disco,
  type EstadoDaViz,
  etiqueta,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  retangulo,
  rodape,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const SOL = '#f7b733';
const TERRA = '#2f7fd0';
const TERRA_ESCURA = '#1d5590';

/** Raio da órbita da Terra, em unidades da cena (1 = 1 UA). */
const UA = 1;
/** Velocidade circular a 1 UA, em km/s — a mesma constante do renderizador. */
const V_CIRCULAR = 29.78;
/** GM do Sol nas unidades da cena: v² · r na órbita circular. */
const GM = V_CIRCULAR * V_CIRCULAR * UA;

/** Passo de integração, em unidades de tempo da cena. */
const PASSO = 0.0006;
/** Sub-passos por quadro: a trajetória fica lisa sem o laço custar caro. */
const SUBPASSOS = 14;

interface Corpo {
  x: number;
  y: number;
  vx: number;
  vy: number;
}

const solar: FabricaViz = (canvas, opcoes): VizDoPuzzle => {
  let estado: EstadoDaViz = {};
  const modo = opcoes.modo ?? 'lancamento';

  let corpo: Corpo | null = null;
  let rastro: [number, number][] = [];
  let voltas = 0;
  let anguloAnterior = 0;

  /** Anuncia o desfecho uma vez e encerra a integração. */
  function encerrar(situacao: string): void {
    corpo = null;
    opcoes.aoMudarEstado?.({ situacao });
  }

  function integrar(): void {
    if (corpo === null) return;

    for (let i = 0; i < SUBPASSOS; i++) {
      if (corpo === null) return;

      const r = Math.hypot(corpo.x, corpo.y);
      // Caiu no Sol.
      if (r < UA * 0.09) {
        encerrar('cai');
        return;
      }
      // Foi embora para não voltar.
      if (r > UA * 4.2) {
        encerrar('escapa');
        return;
      }

      const aceleracao = -GM / (r * r * r);
      corpo.vx += aceleracao * corpo.x * PASSO;
      corpo.vy += aceleracao * corpo.y * PASSO;
      corpo.x += corpo.vx * PASSO;
      corpo.y += corpo.vy * PASSO;

      rastro.push([corpo.x, corpo.y]);
      if (rastro.length > 900) rastro.shift();

      // Duas voltas fechadas bastam para dizer que a órbita se sustenta.
      const angulo = Math.atan2(corpo.y, corpo.x);
      if (anguloAnterior < 0 && angulo >= 0) voltas++;
      anguloAnterior = angulo;
      if (voltas >= 2) {
        encerrar('estavel');
        return;
      }
    }
  }

  /** O Sol, com o halo — o mesmo em todos os três modos. */
  function sol(ctx: CanvasRenderingContext2D, cx: number, cy: number, raio: number): void {
    const halo = ctx.createRadialGradient(cx, cy, raio * 0.5, cx, cy, raio * 3);
    halo.addColorStop(0, 'rgb(247 183 51 / 45%)');
    halo.addColorStop(1, 'rgb(247 183 51 / 0%)');
    ctx.fillStyle = halo;
    ctx.beginPath();
    ctx.arc(cx, cy, raio * 3, 0, Math.PI * 2);
    ctx.fill();
    disco(ctx, cx, cy, raio, SOL);
  }

  /** A Terra, em corte simplificado: oceano, terminador e uma calota. */
  function terra(ctx: CanvasRenderingContext2D, cx: number, cy: number, raio: number): void {
    disco(ctx, cx, cy, raio, TERRA);
    ctx.save();
    ctx.beginPath();
    ctx.arc(cx, cy, raio, 0, Math.PI * 2);
    ctx.clip();
    ctx.fillStyle = TERRA_ESCURA;
    ctx.beginPath();
    ctx.ellipse(cx + raio * 0.55, cy, raio * 0.9, raio, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = 'rgb(255 255 255 / 55%)';
    ctx.beginPath();
    ctx.ellipse(cx, cy - raio * 0.85, raio * 0.55, raio * 0.25, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  // ── Modo 1: o lançamento ────────────────────────────────────────────────

  function desenharLancamento(ctx: CanvasRenderingContext2D, L: number, A: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const velocidade = numeroDe(valores, 'v', 18);
    const situacao = (estado.resultado as { situacao?: string } | null | undefined)?.situacao;
    const ok = info.ok === true;
    const miudo = limitar(A * 0.03, 8, 11);

    titulo(ctx, L, A, 'Órbita circular: nem cair, nem escapar');

    const cx = L * 0.5;
    const cy = A * 0.53;
    const escala = Math.min(L * 0.42, A * 0.34) / (UA * 1.35);

    const px = (x: number): number => cx + x * escala;
    const py = (y: number): number => cy - y * escala;

    // A órbita da Terra: a referência do que se está tentando reproduzir.
    ctx.strokeStyle = cor.trilho;
    ctx.lineWidth = 1.4;
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    ctx.arc(cx, cy, UA * escala, 0, Math.PI * 2);
    ctx.stroke();
    ctx.setLineDash([]);

    sol(ctx, cx, cy, Math.max(9, escala * 0.1));
    terra(ctx, px(UA), py(0), Math.max(5, escala * 0.055));

    integrar();

    // O rastro percorrido.
    if (rastro.length > 1) {
      ctx.strokeStyle = ok ? cor.verde : cor.azul;
      ctx.lineWidth = 2.2;
      ctx.lineJoin = 'round';
      ctx.beginPath();
      for (const [i, p] of rastro.entries()) {
        if (i === 0) ctx.moveTo(px(p[0]), py(p[1]));
        else ctx.lineTo(px(p[0]), py(p[1]));
      }
      ctx.stroke();
    }

    if (corpo !== null) {
      disco(ctx, px(corpo.x), py(corpo.y), 4.5, cor.contraste);
      ctx.strokeStyle = cor.azul;
      ctx.lineWidth = 1.6;
      ctx.beginPath();
      ctx.arc(px(corpo.x), py(corpo.y), 4.5, 0, Math.PI * 2);
      ctx.stroke();
    }

    etiqueta(
      ctx,
      `${velocidade.toFixed(1).replace('.', ',')} km/s`,
      cx,
      A * 0.86,
      miudo * 1.1,
      ok ? cor.verde : cor.texto,
      800,
    );

    rodape(
      ctx,
      L,
      A,
      ok,
      `Órbita circular perfeita a ${V_CIRCULAR} km/s ✔`,
      situacao === 'cai'
        ? 'Devagar demais: o corpo caiu no Sol.'
        : situacao === 'escapa'
          ? 'Rápido demais: o corpo escapou para sempre.'
          : situacao === 'voando'
            ? 'Acompanhando a trajetória…'
            : 'Escolha a velocidade e lance.',
      situacao === 'cai' || situacao === 'escapa' ? cor.erro : cor.fraco,
    );
  }

  // ── Modo 2: o escudo magnético ──────────────────────────────────────────

  function desenharEscudo(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const campo = limitar(numeroDe(valores, 'b', 0), 0, 100);
    const ok = info.ok === true;
    const miudo = limitar(A * 0.03, 8, 11);

    titulo(ctx, L, A, 'O campo que desvia o vento solar para os polos');

    const cx = L * 0.62;
    const cy = A * 0.52;
    const R = Math.min(L * 0.13, A * 0.17);
    // O arco de choque cresce com o campo, mas nunca além da moldura: sem o
    // teto ele passava por cima do título e saía pela direita.
    const alcance = Math.min(
      R * (1.2 + (campo / 100) * 1.5),
      (L - cx) / 1.15,
      (A * 0.66) / 2 / 1.15,
    );

    // O Sol, fora de cena à esquerda, mandando o vento.
    const halo = ctx.createRadialGradient(L * 0.02, cy, 0, L * 0.02, cy, L * 0.3);
    halo.addColorStop(0, 'rgb(247 183 51 / 55%)');
    halo.addColorStop(1, 'rgb(247 183 51 / 0%)');
    ctx.fillStyle = halo;
    ctx.fillRect(0, 0, L * 0.35, A);

    // A magnetosfera: o arco de choque, tanto maior quanto mais forte o campo.
    if (campo > 2) {
      ctx.strokeStyle = ok ? cor.verde : cor.azulClaro;
      ctx.globalAlpha = 0.5 + (campo / 100) * 0.5;
      ctx.lineWidth = 2.4;
      ctx.beginPath();
      ctx.ellipse(
        cx + alcance * 0.15,
        cy,
        alcance,
        alcance * 1.15,
        0,
        Math.PI * 0.42,
        Math.PI * 1.58,
      );
      ctx.stroke();
      ctx.globalAlpha = 1;
    }

    // As linhas de campo, saindo de um polo e entrando no outro.
    ctx.strokeStyle = ok ? cor.verde : cor.azul;
    ctx.globalAlpha = 0.35 + (campo / 100) * 0.5;
    ctx.lineWidth = 1.4;
    for (const largura of [1.4, 2.1, 2.8]) {
      const abertura = Math.min(R * largura * (campo / 100 + 0.35), alcance * 0.92);
      for (const lado of [-1, 1]) {
        ctx.beginPath();
        ctx.moveTo(cx, cy - R);
        ctx.bezierCurveTo(
          cx + lado * abertura,
          cy - R * 1.2,
          cx + lado * abertura,
          cy + R * 1.2,
          cx,
          cy + R,
        );
        ctx.stroke();
      }
    }
    ctx.globalAlpha = 1;

    // O vento solar: partículas vindo da esquerda, desviadas ou não.
    for (let i = 0; i < 16; i++) {
      const faixa = (i / 16 - 0.5) * 2;
      const y0 = cy + faixa * A * 0.34;
      const fase = (t * 0.5 + i / 16) % 1;
      const x = L * 0.04 + fase * (cx - L * 0.04 + alcance);

      const distancia = Math.hypot(x - cx, (y0 - cy) * 0.9);
      const desviada = distancia < alcance && campo > 20;

      // A desviada curva para o polo; a que passa segue reta até a superfície.
      const y = desviada ? y0 + Math.sign(y0 - cy || 1) * (alcance - distancia) * 0.8 : y0;

      const acertou = !desviada && Math.hypot(x - cx, y - cy) < R;
      disco(ctx, x, y, 2.2, acertou ? cor.erro : desviada ? cor.azulClaro : cor.ouro);
    }

    terra(ctx, cx, cy, R);

    // As auroras, onde as partículas desviadas descem.
    if (campo > 40) {
      ctx.strokeStyle = 'rgb(80 220 140 / 70%)';
      ctx.lineWidth = 3;
      for (const lado of [-1, 1]) {
        ctx.beginPath();
        ctx.arc(cx, cy, R * 1.06, lado > 0 ? -1.9 : 1.25, lado > 0 ? -1.25 : 1.9);
        ctx.stroke();
      }
    }

    etiqueta(
      ctx,
      `campo ${Math.round(campo)}%`,
      L * 0.5,
      A * 0.87,
      miudo * 1.1,
      ok ? cor.verde : cor.texto,
      800,
    );
    texto(ctx, 'vento solar', L * 0.06, A * 0.2, miudo, {
      cor: cor.ouro,
      peso: 700,
      alinhamento: 'left',
    });

    rodape(
      ctx,
      L,
      A,
      ok,
      'O escudo desvia o vento solar para os polos ✔',
      'Campo fraco: as partículas chegam à superfície.',
      cor.erro,
    );
  }

  // ── Modo 3: as constantes ───────────────────────────────────────────────

  function desenharConstantes(
    ctx: CanvasRenderingContext2D,
    L: number,
    A: number,
    t: number,
  ): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const gravidade = numeroDe(valores, 'g', 100);
    const distancia = numeroDe(valores, 'd', 100);
    const ok = info.ok === true;
    const miudo = limitar(A * 0.03, 8, 11);

    titulo(ctx, L, A, 'Fora do ponto exato, o planeta deixa de servir');

    const cx = L * 0.2;
    const cy = A * 0.54;
    const escalaOrbita = Math.min(L * 0.42, A * 0.58);

    sol(ctx, cx, cy, Math.max(10, escalaOrbita * 0.09));

    // A faixa habitável: a coroa estreita em que a água é líquida.
    const raioAlvo = escalaOrbita * 0.62;
    ctx.strokeStyle = cor.verde;
    ctx.globalAlpha = 0.25;
    ctx.lineWidth = escalaOrbita * 0.08;
    ctx.beginPath();
    ctx.arc(cx, cy, raioAlvo, -Math.PI / 2.1, Math.PI / 2.1);
    ctx.stroke();
    ctx.globalAlpha = 1;

    // A órbita que a distância escolhida produz.
    const raio = raioAlvo * (distancia / 100);
    ctx.strokeStyle = cor.trilho;
    ctx.lineWidth = 1.2;
    ctx.setLineDash([4, 4]);
    ctx.beginPath();
    ctx.arc(cx, cy, raio, 0, Math.PI * 2);
    ctx.stroke();
    ctx.setLineDash([]);

    // O planeta, com o tamanho puxado pela gravidade.
    const angulo = t * 0.35;
    const px = cx + Math.cos(angulo) * raio;
    const py = cy + Math.sin(angulo) * raio * 0.55;
    terra(ctx, px, py, Math.max(7, escalaOrbita * 0.07 * (gravidade / 100)));

    // ── Os dois mostradores, com o ponto exato marcado ────────────────────
    const bx0 = L * 0.62;
    const bx1 = L * 0.96;

    const mostrador = (indice: number, rotulo: string, valor: number, aviso: string): void => {
      const y = A * 0.3 + indice * A * 0.24;
      const altura = limitar(A * 0.042, 8, 13);
      const dentro = Math.abs(valor - 100) <= 1;

      texto(ctx, rotulo, bx0, y - miudo * 1.1, miudo * 0.95, {
        cor: cor.fraco,
        peso: 700,
        alinhamento: 'left',
      });

      retangulo(ctx, bx0, y, bx1 - bx0, altura, altura / 2, cor.palha, cor.trilho, 1);
      // A faixa boa é estreita de propósito: é a lição inteira do puzzle.
      const xDe = (v: number): number => bx0 + ((limitar(v, 90, 110) - 90) / 20) * (bx1 - bx0);
      retangulo(ctx, xDe(99), y, xDe(101) - xDe(99), altura, 0, 'rgb(47 143 92 / 45%)');

      ctx.fillStyle = dentro ? cor.verde : cor.erro;
      ctx.beginPath();
      ctx.moveTo(xDe(valor), y - 3);
      ctx.lineTo(xDe(valor) - 5, y - 11);
      ctx.lineTo(xDe(valor) + 5, y - 11);
      ctx.closePath();
      ctx.fill();

      texto(
        ctx,
        dentro ? `${valor.toFixed(1).replace('.', ',')}% ✔` : aviso,
        (bx0 + bx1) / 2,
        y + altura + miudo * 1.3,
        miudo * 0.9,
        { cor: dentro ? cor.verde : cor.erro, peso: 700 },
      );
    };

    mostrador(
      0,
      'gravidade',
      gravidade,
      gravidade < 100 ? 'fraca: a atmosfera escapa' : 'forte: nada se levanta',
    );
    mostrador(
      1,
      'distância ao Sol',
      distancia,
      distancia < 100 ? 'perto: a água ferve' : 'longe: a água congela',
    );

    rodape(
      ctx,
      L,
      A,
      ok,
      'Planeta habitável: tudo em equilíbrio ✔',
      'As duas constantes têm de ficar no ponto exato.',
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => {
      if (modo === 'escudo') desenharEscudo(ctx, L, A, t);
      else if (modo === 'constantes') desenharConstantes(ctx, L, A, t);
      else desenharLancamento(ctx, L, A);
    },
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    lancar(valores) {
      const velocidade = Number(valores.v);
      if (!Number.isFinite(velocidade)) return;

      // Sai da posição da Terra, com a velocidade toda na tangente.
      corpo = { x: UA, y: 0, vx: 0, vy: velocidade };
      rastro = [[UA, 0]];
      voltas = 0;
      anguloAnterior = 0;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default solar;
